<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <bits/stdc++.h>
#define MAXN 5000010
#define INFINITY 1000000000
#define P(x,k) (x+(k-1)*n)
using namespace std;
template<typename T> void scan(T &x)
{
    x=0;char c=getchar();bool neg=false;
    while(!isdigit(c)){if(c=='-') neg=true;c=getchar();}
    while(isdigit(c)){x=(x<<1)+(x<<3)+(c^48);c=getchar();}
    if(neg) x=-x;
}
int n,m,k,v1,v2,s,t;
int dist[MAXN];
bool visited[MAXN];
struct Edge
{
    int to,next,v,cost;
}graph[MAXN];
int head[MAXN],cnt=1;
void connect(int from,int to,int val,int cost)
{
    graph[++cnt]=(Edge){to,head[from],val,cost}; head[from]=cnt;
    graph[++cnt]=(Edge){from,head[to],0,-cost}; head[to]=cnt;
}
bool bell()
{
    std::queue<int> q;
    for(int i=s;i<=t;++i) dist[i]=INFINITY,visited[i]=false;
    q.push(s); dist[s]=0; visited[s]=true;
    while(!q.empty())
    {
        int x=q.front(); q.pop(); visited[x]=false;
        for(int i=head[x];i;i=graph[i].next)
        {
            int y=graph[i].to,c=graph[i].cost;
            if(dist[y]<=dist[x]+c||!graph[i].v) continue;
            dist[y]=dist[x]+c;
            if(!visited[y]) {visited[y]=true; q.push(y);}
        }
    }
    return dist[t]!=INFINITY;
}
int augment(int x,int flow_limit)
{
    if(x==t) return flow_limit;
    visited[x]=true;
    int res=flow_limit;
    for(int i=head[x];i;i=graph[i].next)
    {
        int y=graph[i].to,v=graph[i].v;
        if(dist[y]!=dist[x]+graph[i].cost||!v||visited[y]) continue;
        if(int f=augment(y,min(res,v)))
        {
            res-=f;
            graph[i].v-=f;
            graph[i^1].v+=f;
            if(!res) break;
        }
    }
    return flow_limit-res;
}
int minCostFlow()
{
    int total=0, flow;
    while(bell())
        while(flow=augment(s,INFINITY))
            total+=flow*dist[t];
    return total;
}
int main()
{
    scan(n); scan(m); scan(k); scan(v1); scan(v2);
    t=P(n,110)+1;
    for(int i=2;i<=110;++i) connect(P(1,i),t,INFINITY,0);
    for(int i=2;i<=n;++i)
        for(int j=1;j<110;++j)
            connect(P(i,j),P(i,j+1),INFINITY,v1);
    for(int i=1,x;i<=k;++i) {scan(x); connect(s,P(x,1),1,0);}
    for(int i=1;i<=m;++i)
    {
        int x,y;
        scan(x); scan(y);
        for(int j=1;j<110;++j)
            for(int l=1;l<=k;++l)
                connect(P(x,j),P(y,j+1),1,v2*(2*l-1)+v1),
                connect(P(y,j),P(x,j+1),1,v2*(2*l-1)+v1);
    }
    printf("%d",minCostFlow());
    return 0;
}
